19	package org.apache.hadoop.yarn.server.resourcemanager.scheduler.distributed;
20	
21	import org.apache.hadoop.thirdparty.com.google.common.annotations.VisibleForTesting;
22	import org.apache.hadoop.yarn.api.records.NodeState;
