31	
32	import java.util.ArrayList;
33	import java.util.Arrays;
34	import java.util.Comparator;
35	import java.util.List;
36	import java.util.Map;
37	import java.util.Random;
38	import java.util.Set;
39	import java.util.concurrent.ConcurrentHashMap;
40	import java.util.concurrent.Executors;
41	import java.util.concurrent.ScheduledExecutorService;
42	import java.util.concurrent.TimeUnit;
43	import java.util.concurrent.locks.ReentrantReadWriteLock;
44	import java.util.stream.Collectors;
45	
46	import static org.apache.hadoop.yarn.conf.YarnConfiguration.DEFAULT_OPP_CONTAINER_ALLOCATION_NODES_NUMBER_USED;
47	
48	/**
49	 * The NodeQueueLoadMonitor keeps track of load metrics (such as queue length
50	 * and total wait time) associated with Container Queues on the Node Manager.
51	 * It uses this information to periodically sort the Nodes from least to most
52	 * loaded.
53	 */
54	public class NodeQueueLoadMonitor implements ClusterMonitor {
55	
56	  protected final static Logger LOG = LoggerFactory.
57	      getLogger(NodeQueueLoadMonitor.class);
58	
59	  protected int numNodesForAnyAllocation =
60	      DEFAULT_OPP_CONTAINER_ALLOCATION_NODES_NUMBER_USED;
61	
62	  /**
63	   * The comparator used to specify the metric against which the load
64	   * of two Nodes are compared.
65	   */
66	  public enum LoadComparator implements Comparator<ClusterNode> {
67	    QUEUE_LENGTH,
68	    QUEUE_WAIT_TIME;
69	
70	    @Override
71	    public int compare(ClusterNode o1, ClusterNode o2) {
72	      if (getMetric(o1) == getMetric(o2)) {
73	        return (int)(o2.getTimestamp() - o1.getTimestamp());
74	      }
75	      return getMetric(o1) - getMetric(o2);
76	    }
77	
78	    public int getMetric(ClusterNode c) {
79	      return (this == QUEUE_LENGTH) ?
80	          c.getQueueLength().get() : c.getQueueWaitTime().get();
81	    }
82	
83	    /**
84	     * Increment the metric by a delta if it is below the threshold.
85	     * @param c ClusterNode
86	     * @param incrementSize increment size
87	     * @return true if the metric was below threshold and was incremented.
88	     */
89	    public boolean compareAndIncrement(ClusterNode c, int incrementSize) {
90	      if(this == QUEUE_LENGTH) {
91	        int ret = c.getQueueLength().addAndGet(incrementSize);
92	        if (ret <= c.getQueueCapacity()) {
93	          return true;
94	        }
95	        c.getQueueLength().addAndGet(-incrementSize);
96	        return false;
97	      }
98	      // for queue wait time, we don't have any threshold.
99	      return true;
100	    }
101	  }
102	
103	  private final ScheduledExecutorService scheduledExecutor;
104	
105	  protected final List<NodeId> sortedNodes;
106	  protected final Map<NodeId, ClusterNode> clusterNodes =
107	      new ConcurrentHashMap<>();
108	  protected final Map<String, RMNode> nodeByHostName =
109	      new ConcurrentHashMap<>();
110	  protected final Map<String, Set<NodeId>> nodeIdsByRack =
111	      new ConcurrentHashMap<>();
112	  protected final LoadComparator comparator;
113	  protected QueueLimitCalculator thresholdCalculator;
114	  protected ReentrantReadWriteLock sortedNodesLock = new ReentrantReadWriteLock();
115	  protected ReentrantReadWriteLock clusterNodesLock =
116	      new ReentrantReadWriteLock();
117	
118	  Runnable computeTask = new Runnable() {
119	    @Override
120	    public void run() {
121	      ReentrantReadWriteLock.WriteLock writeLock = sortedNodesLock.writeLock();
122	      writeLock.lock();
123	      try {
124	        try {
125	          updateSortedNodes();
126	        } catch (Exception ex) {
127	          LOG.warn("Got Exception while sorting nodes..", ex);
128	        }
129	        if (thresholdCalculator != null) {
130	          thresholdCalculator.update();
131	        }
132	      } finally {
133	        writeLock.unlock();
134	      }
135	    }
136	  };
137	
138	  @VisibleForTesting
139	  NodeQueueLoadMonitor(LoadComparator comparator) {
140	    this.sortedNodes = new ArrayList<>();
141	    this.comparator = comparator;
142	    this.scheduledExecutor = null;
143	  }
144	
145	  public NodeQueueLoadMonitor(long nodeComputationInterval,
146	      LoadComparator comparator, int numNodes) {
147	    this.sortedNodes = new ArrayList<>();
148	    this.scheduledExecutor = Executors.newScheduledThreadPool(1);
149	    this.comparator = comparator;
150	    this.scheduledExecutor.scheduleAtFixedRate(computeTask,
151	        nodeComputationInterval, nodeComputationInterval,
152	        TimeUnit.MILLISECONDS);
153	    numNodesForAnyAllocation = numNodes;
154	  }
155	
156	  protected void updateSortedNodes() {
157	    List<NodeId> nodeIds = sortNodes(true).stream()
158	        .map(n -> n.nodeId)
159	        .collect(Collectors.toList());
160	    sortedNodes.clear();
161	    sortedNodes.addAll(nodeIds);
162	  }
163	
164	  List<NodeId> getSortedNodes() {
165	    return sortedNodes;
166	  }
167	
168	  public QueueLimitCalculator getThresholdCalculator() {
169	    return thresholdCalculator;
170	  }
171	
172	  public void stop() {
173	    if (scheduledExecutor != null) {
174	      scheduledExecutor.shutdown();
175	    }
176	  }
177	
178	  Map<NodeId, ClusterNode> getClusterNodes() {
179	    return clusterNodes;
180	  }
181	
182	  Comparator<ClusterNode> getComparator() {
183	    return comparator;
184	  }
185	
186	  public void initThresholdCalculator(float sigma, int limitMin, int limitMax) {
187	    this.thresholdCalculator =
188	        new QueueLimitCalculator(this, sigma, limitMin, limitMax);
189	  }
190	
191	  @Override
192	  public void addNode(List<NMContainerStatus> containerStatuses,
193	      RMNode rmNode) {
194	    this.nodeByHostName.put(rmNode.getHostName(), rmNode);
195	    addIntoNodeIdsByRack(rmNode);
196	    // Ignoring this currently : at least one NODE_UPDATE heartbeat is
197	    // required to ensure node eligibility.
198	  }
199	
200	  @Override
201	  public void removeNode(RMNode removedRMNode) {
202	    LOG.info("Node delete event for: {}", removedRMNode.getNode().getName());
203	    this.nodeByHostName.remove(removedRMNode.getHostName());
204	    removeFromNodeIdsByRack(removedRMNode);
205	    ReentrantReadWriteLock.WriteLock writeLock = clusterNodesLock.writeLock();
206	    writeLock.lock();
207	    ClusterNode node;
208	    try {
209	      node = this.clusterNodes.remove(removedRMNode.getNodeID());
210	      onNodeRemoved(node);
211	    } finally {
212	      writeLock.unlock();
213	    }
214	    if (LOG.isDebugEnabled()) {
215	      if (node != null) {
216	        LOG.debug("Delete ClusterNode: " + removedRMNode.getNodeID());
217	      } else {
218	        LOG.debug("Node not in list!");
219	      }
220	    }
221	  }
222	
223	  /**
224	   * Provide an integration point for extended class
225	   * @param node the node removed
226	   */
227	  protected void onNodeRemoved(ClusterNode node) {
228	  }
229	
230	  @Override
231	  public void updateNode(RMNode rmNode) {
232	    LOG.debug("Node update event from: {}", rmNode.getNodeID());
233	    OpportunisticContainersStatus opportunisticContainersStatus =
234	        rmNode.getOpportunisticContainersStatus();
235	    if (opportunisticContainersStatus == null) {
236	      opportunisticContainersStatus =
237	          OpportunisticContainersStatus.newInstance();
238	    }
239	
240	    // Add nodes to clusterNodes. If estimatedQueueTime is -1, ignore node
241	    // UNLESS comparator is based on queue length.
242	    ReentrantReadWriteLock.WriteLock writeLock = clusterNodesLock.writeLock();
243	    writeLock.lock();
244	    try {
245	      ClusterNode clusterNode = this.clusterNodes.get(rmNode.getNodeID());
246	      if (clusterNode == null) {
247	        onNewNodeAdded(rmNode, opportunisticContainersStatus);
248	      } else {
249	        onExistingNodeUpdated(rmNode, clusterNode, opportunisticContainersStatus);
250	      }
251	    } finally {
252	      writeLock.unlock();
253	    }
254	  }
255	
256	  protected void onNewNodeAdded(
257	      RMNode rmNode, OpportunisticContainersStatus status) {
258	    int opportQueueCapacity = status.getOpportQueueCapacity();
259	    int estimatedQueueWaitTime = status.getEstimatedQueueWaitTime();
260	    int waitQueueLength = status.getWaitQueueLength();
261	
262	    if (rmNode.getState() != NodeState.DECOMMISSIONING &&
263	        (estimatedQueueWaitTime != -1 ||
264	            comparator == LoadComparator.QUEUE_LENGTH)) {
265	      this.clusterNodes.put(rmNode.getNodeID(),
266	          new ClusterNode(rmNode.getNodeID())
267	              .setQueueWaitTime(estimatedQueueWaitTime)
268	              .setQueueLength(waitQueueLength)
269	              .setNodeLabels(rmNode.getNodeLabels())
270	              .setQueueCapacity(opportQueueCapacity));
271	      LOG.info(
272	          "Inserting ClusterNode [{}] with queue wait time [{}] and "
273	              + "wait queue length [{}]",
274	          rmNode.getNode(),
275	          estimatedQueueWaitTime,
276	          waitQueueLength
277	      );
278	    } else {
279	      LOG.warn(
280	          "IGNORING ClusterNode [{}] with queue wait time [{}] and "
281	              + "wait queue length [{}]",
282	          rmNode.getNode(),
283	          estimatedQueueWaitTime,
284	          waitQueueLength
285	      );
286	    }
287	  }
288	
289	  protected void onExistingNodeUpdated(
290	      RMNode rmNode, ClusterNode clusterNode,
291	      OpportunisticContainersStatus status) {
292	
293	    int estimatedQueueWaitTime = status.getEstimatedQueueWaitTime();
294	    int waitQueueLength = status.getWaitQueueLength();
295	
296	    if (rmNode.getState() != NodeState.DECOMMISSIONING &&
297	        (estimatedQueueWaitTime != -1 ||
298	            comparator == LoadComparator.QUEUE_LENGTH)) {
299	      clusterNode
300	          .setQueueWaitTime(estimatedQueueWaitTime)
301	          .setQueueLength(waitQueueLength)
302	          .setNodeLabels(rmNode.getNodeLabels())
303	          .updateTimestamp();
304	      LOG.debug("Updating ClusterNode [{}] with queue wait time [{}] and"
305	              + " wait queue length [{}]", rmNode.getNodeID(),
306	          estimatedQueueWaitTime, waitQueueLength);
307	
308	    } else {
309	      this.clusterNodes.remove(rmNode.getNodeID());
310	      LOG.info("Deleting ClusterNode [" + rmNode.getNodeID() + "] " +
311	          "with queue wait time [" + clusterNode.getQueueWaitTime() + "] and " +
312	          "wait queue length [" + clusterNode.getQueueLength() + "]");
313	    }
314	  }
315	
316	  @Override
317	  public void updateNodeResource(RMNode rmNode, ResourceOption resourceOption) {
318	    LOG.debug("Node resource update event from: {}", rmNode.getNodeID());
319	    // Ignoring this currently.
320	  }
321	
322	  /**
323	   * Returns all Node Ids as ordered list from Least to Most Loaded.
324	   * @return ordered list of nodes
325	   */
326	  public List<NodeId> selectNodes() {
327	    return selectLeastLoadedNodes(-1);
328	  }
329	
330	  /**
331	   * Returns 'K' of the least Loaded Node Ids as ordered list.
332	   * @param k max number of nodes to return
333	   * @return ordered list of nodes
334	   */
335	  public List<NodeId> selectLeastLoadedNodes(int k) {
336	    ReentrantReadWriteLock.ReadLock readLock = sortedNodesLock.readLock();
337	    readLock.lock();
338	    try {
339	      List<NodeId> retVal = ((k < this.sortedNodes.size()) && (k >= 0)) ?
340	          new ArrayList<>(this.sortedNodes).subList(0, k) :
341	          new ArrayList<>(this.sortedNodes);
342	      return retVal;
343	    } finally {
344	      readLock.unlock();
345	    }
346	  }
347	
348	  public RMNode selectLocalNode(String hostName, Set<String> blacklist) {
349	    if (blacklist.contains(hostName)) {
350	      return null;
351	    }
352	    RMNode node = nodeByHostName.get(hostName);
353	    if (node != null) {
354	      ClusterNode clusterNode = clusterNodes.get(node.getNodeID());
355	      if (comparator.compareAndIncrement(clusterNode, 1)) {
356	        return node;
357	      }
358	    }
359	    return null;
360	  }
361	
362	  public RMNode selectRackLocalNode(String rackName, Set<String> blacklist) {
363	    Set<NodeId> nodesOnRack = nodeIdsByRack.get(rackName);
364	    if (nodesOnRack != null) {
365	      for (NodeId nodeId : nodesOnRack) {
366	        if (!blacklist.contains(nodeId.getHost())) {
367	          ClusterNode node = clusterNodes.get(nodeId);
368	          if (node != null && comparator.compareAndIncrement(node, 1)) {
369	            return nodeByHostName.get(nodeId.getHost());
370	          }
371	        }
372	      }
373	    }
374	    return null;
375	  }
376	
377	  public RMNode selectAnyNode(Set<String> blacklist) {
378	    List<NodeId> nodeIds = getCandidatesForSelectAnyNode();
379	    int size = nodeIds.size();
380	    if (size <= 0) {
381	      return null;
382	    }
383	    Random rand = new Random();
384	    int startIndex = rand.nextInt(size);
385	    for (int i = 0; i < size; ++i) {
386	      int index = i + startIndex;
387	      index %= size;
388	      NodeId nodeId = nodeIds.get(index);
389	      if (nodeId != null && !blacklist.contains(nodeId.getHost())) {
390	        ClusterNode node = clusterNodes.get(nodeId);
391	        if (node != null && comparator.compareAndIncrement(node, 1)) {
392	          return nodeByHostName.get(nodeId.getHost());
393	        }
394	      }
395	    }
396	    return null;
397	  }
398	
399	  protected List<NodeId> getCandidatesForSelectAnyNode() {
400	    return selectLeastLoadedNodes(numNodesForAnyAllocation);
401	  }
402	
403	  protected void removeFromNodeIdsByRack(RMNode removedNode) {
404	    nodeIdsByRack.computeIfPresent(removedNode.getRackName(),
405	        (k, v) -> v).remove(removedNode.getNodeID());
406	  }
407	
408	  protected void addIntoNodeIdsByRack(RMNode addedNode) {
409	    nodeIdsByRack.compute(addedNode.getRackName(), (k, v) -> v == null ?
410	        ConcurrentHashMap.newKeySet() : v).add(addedNode.getNodeID());
411	  }
412	
413	  protected List<ClusterNode> sortNodes(boolean excludeFullNodes) {
414	    ReentrantReadWriteLock.ReadLock readLock = clusterNodesLock.readLock();
415	    readLock.lock();
416	    try {
417	      ArrayList<ClusterNode> aList = new ArrayList<>(this.clusterNodes.values());
418	      List<ClusterNode> retList = new ArrayList<>();
419	      Object[] nodes = aList.toArray();
420	      // Collections.sort would do something similar by calling Arrays.sort
421	      // internally but would finally iterate through the input list (aList)
422	      // to reset the value of each element. Since we don't really care about
423	      // 'aList', we can use the iteration to create the list of nodeIds which
424	      // is what we ultimately care about.
425	      Arrays.sort(nodes, (Comparator)comparator);
426	      for (int j=0; j < nodes.length; j++) {
427	        ClusterNode cNode = (ClusterNode)nodes[j];
428	        // Only add node to the result list when either condition is met:
429	        // 1. we don't exclude full nodes
430	        // 2. we do exclude full nodes, but the current node is not full
431	        if (!excludeFullNodes || !cNode.isQueueFull()) {
432	          retList.add(cNode);
433	        }
434	      }
435	      return retList;
436	    } finally {
437	      readLock.unlock();
438	    }
439	  }
440	
441	}
