19	package org.apache.hadoop.yarn.server.resourcemanager.scheduler.distributed;
20	
21	import java.util.Collection;
22	import java.util.HashSet;
23	import java.util.concurrent.atomic.AtomicInteger;
24	import org.apache.hadoop.yarn.api.records.NodeId;
25	
26	/**
27	 * Represents a node in the cluster from the NodeQueueLoadMonitor's perspective
28	 */
29	public class ClusterNode {
30	  private final AtomicInteger queueLength = new AtomicInteger(0);
31	  private final AtomicInteger queueWaitTime = new AtomicInteger(-1);
32	  private long timestamp;
33	  final NodeId nodeId;
34	  private int queueCapacity = 0;
35	  private final HashSet<String> labels;
36	
37	  public ClusterNode(NodeId nodeId) {
38	    this.nodeId = nodeId;
39	    this.labels = new HashSet<>();
40	    updateTimestamp();
41	  }
42	
43	  public ClusterNode setQueueLength(int qLength) {
44	    this.queueLength.set(qLength);
45	    return this;
46	  }
47	
48	  public ClusterNode setQueueWaitTime(int wTime) {
49	    this.queueWaitTime.set(wTime);
50	    return this;
51	  }
52	
53	  public ClusterNode updateTimestamp() {
54	    this.timestamp = System.currentTimeMillis();
55	    return this;
56	  }
57	
58	  public ClusterNode setQueueCapacity(int capacity) {
59	    this.queueCapacity = capacity;
60	    return this;
61	  }
62	
63	  public ClusterNode setNodeLabels(Collection<String> labelsToAdd) {
64	    labels.clear();
65	    labels.addAll(labelsToAdd);
66	    return this;
67	  }
68	
69	  public boolean hasLabel(String label) {
70	    return this.labels.contains(label);
71	  }
72	
73	  public long getTimestamp() {
74	    return this.timestamp;
75	  }
76	
77	  public AtomicInteger getQueueLength() {
78	    return this.queueLength;
79	  }
80	
81	  public AtomicInteger getQueueWaitTime() {
82	    return this.queueWaitTime;
83	  }
84	
85	  public int getQueueCapacity() {
86	    return this.queueCapacity;
87	  }
88	
89	  public boolean isQueueFull() {
90	    return this.queueCapacity > 0 &&
91	        this.queueLength.get() >= this.queueCapacity;
92	  }
93	}
