47	/**
48	 * <p>
49	 * The CentralizedOpportunisticContainerAllocator allocates opportunistic
50	 * containers by considering all the nodes present in the cluster, after
51	 * modifying the container sizes to respect the limits set by the
52	 * ResourceManager. It tries to distribute the containers as evenly as
53	 * possible.
54	 * </p>
55	 */
56	public class CentralizedOpportunisticContainerAllocator extends
57	    OpportunisticContainerAllocator {
58	
59	  private static final Logger LOG =
60	      LoggerFactory.getLogger(CentralizedOpportunisticContainerAllocator.class);
61	
62	  private NodeQueueLoadMonitor nodeQueueLoadMonitor;
63	  private OpportunisticSchedulerMetrics metrics =
64	      OpportunisticSchedulerMetrics.getMetrics();
65	
66	  /**
67	   * Create a new Centralized Opportunistic Container Allocator.
68	   * @param tokenSecretManager TokenSecretManager
69	   */
70	  public CentralizedOpportunisticContainerAllocator(
71	      BaseContainerTokenSecretManager tokenSecretManager) {
72	    super(tokenSecretManager);
73	  }
74	
75	  /**
76	   * Create a new Centralized Opportunistic Container Allocator.
77	   * @param tokenSecretManager TokenSecretManager
78	   * @param maxAllocationsPerAMHeartbeat max number of containers to be
79	   *                                     allocated in one AM heartbeat
80	   */
81	  public CentralizedOpportunisticContainerAllocator(
82	      BaseContainerTokenSecretManager tokenSecretManager,
83	      int maxAllocationsPerAMHeartbeat,
84	      NodeQueueLoadMonitor nodeQueueLoadMonitor) {
85	    super(tokenSecretManager, maxAllocationsPerAMHeartbeat);
86	    this.nodeQueueLoadMonitor = nodeQueueLoadMonitor;
87	  }
88	
89	  @VisibleForTesting
90	  void setNodeQueueLoadMonitor(NodeQueueLoadMonitor nodeQueueLoadMonitor) {
91	    this.nodeQueueLoadMonitor = nodeQueueLoadMonitor;
92	  }
93	
94	  @Override
95	  public List<Container> allocateContainers(
96	      ResourceBlacklistRequest blackList, List<ResourceRequest> oppResourceReqs,
97	      ApplicationAttemptId applicationAttemptId,
98	      OpportunisticContainerContext opportContext, long rmIdentifier,
99	      String appSubmitter) throws YarnException {
100	
101	    updateBlacklist(blackList, opportContext);
102	
103	    // Add OPPORTUNISTIC requests to the outstanding ones.
104	    opportContext.addToOutstandingReqs(oppResourceReqs);
105	
106	    Set<String> nodeBlackList = new HashSet<>(opportContext.getBlacklist());
107	    List<Container> allocatedContainers = new ArrayList<>();
108	    int maxAllocationsPerAMHeartbeat = getMaxAllocationsPerAMHeartbeat();
109	    List<Map<Resource, List<Allocation>>> allocations = new ArrayList<>();
110	
111	    for (SchedulerRequestKey schedulerKey :
112	        opportContext.getOutstandingOpReqs().descendingKeySet()) {
113	      // Allocated containers :
114	      //  Key = Requested Capability,
115	      //  Value = List of Containers of given cap (the actual container size
116	      //          might be different than what is requested, which is why
117	      //          we need the requested capability (key) to match against
118	      //          the outstanding reqs)
119	      int remAllocs = -1;
120	      if (maxAllocationsPerAMHeartbeat > 0) {
121	        remAllocs =
122	            maxAllocationsPerAMHeartbeat - getTotalAllocations(allocations);
123	        if (remAllocs <= 0) {
124	          LOG.info("Not allocating more containers as we have reached max "
125	                  + "allocations per AM heartbeat {}",
126	              maxAllocationsPerAMHeartbeat);
127	          break;
128	        }
129	      }
130	      Map<Resource, List<Allocation>> allocation = allocatePerSchedulerKey(
131	          rmIdentifier, opportContext, schedulerKey, applicationAttemptId,
132	          appSubmitter, nodeBlackList, remAllocs);
133	      if (allocation.size() > 0) {
134	        allocations.add(allocation);
135	      }
136	    }
137	    matchAllocation(allocations, allocatedContainers, opportContext);
138	    return allocatedContainers;
139	  }
