141	  private Map<Resource, List<Allocation>> allocatePerSchedulerKey(
142	      long rmIdentifier, OpportunisticContainerContext appContext,
143	      SchedulerRequestKey schedKey, ApplicationAttemptId appAttId,
144	      String userName, Set<String> blackList, int maxAllocations)
145	      throws YarnException {
146	    Map<Resource, List<Allocation>> allocations = new HashMap<>();
147	    int totalAllocated = 0;
148	    for (EnrichedResourceRequest enrichedAsk :
149	        appContext.getOutstandingOpReqs().get(schedKey).values()) {
150	      int remainingAllocs = -1;
151	      if (maxAllocations > 0) {
152	        remainingAllocs = maxAllocations - totalAllocated;
153	        if (remainingAllocs <= 0) {
154	          LOG.info("Not allocating more containers as max allocations per AM "
155	              + "heartbeat {} has reached", getMaxAllocationsPerAMHeartbeat());
156	          break;
157	        }
158	      }
159	
160	      totalAllocated += allocateContainersPerRequest(rmIdentifier,
161	          appContext.getAppParams(),
162	          appContext.getContainerIdGenerator(), blackList,
163	          appAttId, userName, allocations, enrichedAsk,
164	          remainingAllocs);
165	      ResourceRequest anyAsk = enrichedAsk.getRequest();
166	      if (!allocations.isEmpty()) {
167	        LOG.info("Opportunistic allocation requested for [priority={}, "
168	                + "allocationRequestId={}, num_containers={}, capability={}] "
169	                + "allocated = {}", anyAsk.getPriority(),
170	            anyAsk.getAllocationRequestId(), anyAsk.getNumContainers(),
171	            anyAsk.getCapability(), allocations.keySet());
172	      }
173	    }
174	    return allocations;
175	  }
176	
177	  @SuppressWarnings("checkstyle:parameternumber")
178	  private int allocateContainersPerRequest(long rmIdentifier,
179	      AllocationParams appParams, ContainerIdGenerator idCounter,
180	      Set<String> blacklist,
181	      ApplicationAttemptId id,
182	      String userName, Map<Resource, List<Allocation>> allocations,
183	      EnrichedResourceRequest enrichedAsk, int maxAllocations)
184	      throws YarnException {
185	    ResourceRequest anyAsk = enrichedAsk.getRequest();
186	    int totalAllocated = 0;
187	    int maxToAllocate = anyAsk.getNumContainers()
188	        - (allocations.isEmpty() ? 0 :
189	        allocations.get(anyAsk.getCapability()).size());
190	    if (maxAllocations >= 0) {
191	      maxToAllocate = Math.min(maxAllocations, maxToAllocate);
192	    }
193	
194	    // allocate node local
195	    if (maxToAllocate > 0) {
196	      Map<String, AtomicInteger> nodeLocations = enrichedAsk.getNodeMap();
197	      for (Map.Entry<String, AtomicInteger> nodeLocation :
198	          nodeLocations.entrySet()) {
199	        int numContainers = nodeLocation.getValue().get();
200	        numContainers = Math.min(numContainers, maxToAllocate);
201	        List<Container> allocatedContainers =
202	            allocateNodeLocal(enrichedAsk, nodeLocation.getKey(),
203	                numContainers, rmIdentifier, appParams, idCounter, blacklist,
204	                id, userName, allocations);
205	        totalAllocated += allocatedContainers.size();
206	        maxToAllocate -= allocatedContainers.size();
207	        // no more containers to allocate
208	        if (maxToAllocate <= 0) {
209	          break;
210	        }
211	      }
212	    }
213	
214	    // if still left, allocate rack local
215	    if (maxToAllocate > 0) {
216	      Map<String, AtomicInteger> rackLocations = enrichedAsk.getRackMap();
217	      for (Map.Entry<String, AtomicInteger> rack : rackLocations.entrySet()) {
218	        int numContainers = rack.getValue().get();
219	        numContainers = Math.min(numContainers, maxToAllocate);
220	        List<Container> allocatedContainers =
221	            allocateRackLocal(enrichedAsk, rack.getKey(), numContainers,
222	                rmIdentifier, appParams, idCounter, blacklist, id,
223	                userName, allocations);
224	        totalAllocated += allocatedContainers.size();
225	        maxToAllocate -= allocatedContainers.size();
226	        // no more containers to allocate
227	        if (maxToAllocate <= 0) {
228	          break;
229	        }
230	      }
231	    }
232	
233	    // if still left, try on ANY
234	    if (maxToAllocate > 0) {
235	      List<Container> allocatedContainers = allocateAny(enrichedAsk,
236	          maxToAllocate, rmIdentifier, appParams, idCounter, blacklist,
237	          id, userName, allocations);
238	      totalAllocated += allocatedContainers.size();
239	    }
240	    return totalAllocated;
241	  }
