243	  @SuppressWarnings("checkstyle:parameternumber")
244	  private List<Container> allocateNodeLocal(
245	      EnrichedResourceRequest enrichedAsk,
246	      String nodeLocation,
247	      int toAllocate, long rmIdentifier,
248	      AllocationParams appParams, ContainerIdGenerator idCounter,
249	      Set<String> blacklist,
250	      ApplicationAttemptId id,
251	      String userName, Map<Resource, List<Allocation>> allocations)
252	      throws YarnException {
253	    List<Container> allocatedContainers = new ArrayList<>();
254	    while (toAllocate > 0) {
255	      RMNode node = nodeQueueLoadMonitor.selectLocalNode(nodeLocation,
256	          blacklist);
257	      if (node != null) {
258	        toAllocate--;
259	        Container container = createContainer(rmIdentifier, appParams,
260	            idCounter, id, userName, allocations, nodeLocation,
261	            enrichedAsk.getRequest(), convertToRemoteNode(node));
262	        allocatedContainers.add(container);
263	        LOG.info("Allocated [{}] as opportunistic at location [{}]",
264	            container.getId(), nodeLocation);
265	        metrics.incrNodeLocalOppContainers();
266	      } else {
267	        // we couldn't allocate any - break the loop.
268	        break;
269	      }
270	    }
271	    return allocatedContainers;
272	  }
