196	
197	    // Test Mean Calculation
198	    selector.initThresholdCalculator(0, 6, 100);
199	    QueueLimitCalculator calculator = selector.getThresholdCalculator();
200	    ContainerQueuingLimit containerQueuingLimit = calculator
201	        .createContainerQueuingLimit();
202	    Assert.assertEquals(6, containerQueuingLimit.getMaxQueueLength());
203	    Assert.assertEquals(-1, containerQueuingLimit.getMaxQueueWaitTimeInMs());
204	    selector.computeTask.run();
205	    containerQueuingLimit = calculator.createContainerQueuingLimit();
206	    Assert.assertEquals(10, containerQueuingLimit.getMaxQueueLength());
207	    Assert.assertEquals(-1, containerQueuingLimit.getMaxQueueWaitTimeInMs());
208	
209	    // Test Limits do not exceed specified max
210	    selector.updateNode(createRMNode("h1", 1, -1, 110));
211	    selector.updateNode(createRMNode("h2", 2, -1, 120));
212	    selector.updateNode(createRMNode("h3", 3, -1, 130));
