215	    selector.updateNode(createRMNode("h6", 6, -1, 160));
216	    selector.computeTask.run();
217	    containerQueuingLimit = calculator.createContainerQueuingLimit();
218	    Assert.assertEquals(100, containerQueuingLimit.getMaxQueueLength());
219	
220	    // Test Limits do not go below specified min
